import{_ as e,g as a,e as o,a4 as r}from"./chunks/framework.CEYJDsBW.js";const k=JSON.parse('{"title":"dev.dubhe.anvilcraft.block.logistics.storage","description":"","frontmatter":{},"headers":[],"relativePath":"anvilcraft/26.1/api/dev-dubhe-anvilcraft-block-logistics-storage.md","filePath":"anvilcraft/26.1/api/dev-dubhe-anvilcraft-block-logistics-storage.md"}'),c={name:"anvilcraft/26.1/api/dev-dubhe-anvilcraft-block-logistics-storage.md"};function l(d,t,i,s,b,n){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="dev-dubhe-anvilcraft-block-logistics-storage" tabindex="-1">dev.dubhe.anvilcraft.block.logistics.storage <a class="header-anchor" href="#dev-dubhe-anvilcraft-block-logistics-storage" aria-label="Permalink to &quot;dev.dubhe.anvilcraft.block.logistics.storage&quot;">​</a></h1><h2 id="abstractstorageportblock" tabindex="-1">AbstractStoragePortBlock <a class="header-anchor" href="#abstractstorageportblock" aria-label="Permalink to &quot;AbstractStoragePortBlock&quot;">​</a></h2><p><code>public abstract class AbstractStoragePortBlock extends BaseEntityBlock implements IHammerRemovable</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/AbstractStoragePortBlock.java#L37" target="_blank" rel="noreferrer">类型声明</a></p><p>仓储端口方块父类：把左右键行为重定向到 IStoragePort 的实现。 右键走原版方块交互入口，转发给 IStoragePort#onRightClick；左键没有原版方块入口 （挖掘在网络层被事件拦截），因此由 #interceptsLeftClick 判定是否拦截挖掘、 #onLeftClick 执行服务端行为，两者分别由左键事件与取出请求包调用。 三个端口都没有容积以外的特殊交互，渲染形状统一为模型，故一并放在父类里。 外观由 #TYPE 决定：连接的核心是潜影集装箱还是超维存储站， 由各端口方块实体在重校验相连关系时用 #refreshType 刷新。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final EnumProperty&lt;StoragePortType&gt; TYPE</code></td><td>端口外观类型：连接的核心是潜影集装箱（sc）还是超维存储站（hd）<br>初值 <code>EnumProperty.create(&quot;type&quot;, StoragePortType.class)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/AbstractStoragePortBlock.java#L39" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static void refreshType(Level level, BlockPos pos, @Nullable BlockPos core)</code></td><td>按连通组件的核心刷新端口外观：唯一核心是超维存储站时显示 hd，其余情况显示 sc。 未连接核心、连接多个核心（连通组件接触多个核心时不工作）以及核心仍是潜影集装箱时 都回到 sc。外观在服务端推导，经方块状态同步给客户端。<br>参数 <code>level</code> 世界<br>参数 <code>pos</code> 端口位置<br>参数 <code>core</code> 连通组件接触到的唯一核心主方块坐标；没有核心或连接多个核心时为 null<br>实现调用 <code>level.isClientSide()</code><br>实现调用 <code>level.getBlockState(pos)</code><br>实现调用 <code>state.hasProperty(AbstractStoragePortBlock.TYPE)</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/StorageFluidPortBlockEntity.java#L381" target="_blank" rel="noreferrer">调用处 StorageFluidPortBlockEntity.validateLink</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/AbstractStoragePortBlock.java#L63" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public boolean interceptsLeftClick(Level level, BlockPos pos, Player player, @Nullable BlockHitResult hit)</code></td><td>该左键是否属于端口行为（拦截挖掘）。<br>参数 <code>player</code> 玩家<br>参数 <code>hit</code> 左键命中点；无法取得时为 null<br>返回 是否拦截挖掘<br>末尾返回 <code>level.getBlockEntity(pos) instanceof IStoragePort port &amp;&amp; port.interceptsLeftClick(player, hit)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/AbstractStoragePortBlock.java#L108" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public boolean onLeftClick(Level level, BlockPos pos, Player player)</code></td><td>执行端口的左键行为（仅服务端调用）。<br>返回 是否已处理<br><code>(!(level.getBlockEntity(pos) instanceof IStoragePort port))</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>port.onClick(ClickAction.PRIMARY, player, InteractionHand.MAIN_HAND, ports)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/AbstractStoragePortBlock.java#L117" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="storagefluidportblock" tabindex="-1">StorageFluidPortBlock <a class="header-anchor" href="#storagefluidportblock" aria-label="Permalink to &quot;StorageFluidPortBlock&quot;">​</a></h2><p><code>public class StorageFluidPortBlock extends AbstractStoragePortBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L31" target="_blank" rel="noreferrer">类型声明</a></p><p>仓储流体端口方块。 作为面相邻潜影集装箱 / 超维存储站的外部流体存储，连接关系与仓储端口一致且可互相延伸； 内部容量 128 B 且只能存储单一流体。手持门格海绵右键清除内部流体；拆除时流体随掉落物保留。 左右键行为本身定义在 StorageFluidPortBlockEntity，本类只负责掉落物、克隆与同步。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>@Override public boolean hasAnalogOutputSignal(BlockState state)</code></td><td>末尾返回 <code>true</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L32" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public StorageFluidPortBlock(Properties properties)</code></td><td>执行 <code>super(properties)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L55" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public ItemStack getCloneItemStack( LevelReader level, BlockPos pos, BlockState state, boolean includeData, Player player )</code></td><td>末尾返回 <code>stack</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L72" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public BlockState playerWillDestroy(Level level, BlockPos pos, BlockState state, Player player)</code></td><td>末尾返回 <code>super.playerWillDestroy(level, pos, state, player)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L93" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public BlockEntity newBlockEntity(BlockPos blockPos, BlockState blockState)</code></td><td>为指定位置和状态创建方块实体。<br>末尾返回 <code>ModBlockEntities.STORAGE_FLUID_PORT.create(blockPos, blockState)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L106" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public &lt;T extends BlockEntity&gt; BlockEntityTicker&lt;T&gt; getTicker( Level level, BlockState state, BlockEntityType&lt;T&gt; blockEntityType )</code></td><td><code>(level.isClientSide())</code> 成立时提前返回 <code>null</code><br>末尾返回 <code>createTickerHelper( blockEntityType, ModBlockEntities.STORAGE_FLUID_PORT.get(), (level1, pos, state1, entity) -&gt; entity.tickServer() )</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StorageFluidPortBlock.java#L112" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="storageportblock" tabindex="-1">StoragePortBlock <a class="header-anchor" href="#storageportblock" aria-label="Permalink to &quot;StoragePortBlock&quot;">​</a></h2><p><code>public class StoragePortBlock extends AbstractStoragePortBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L34" target="_blank" rel="noreferrer">类型声明</a></p><p>仓储端口方块。 面相邻潜影集装箱 / 超维存储站（可沿端口链延伸）使用；右键物品标记并塞入、 双击塞入全部、左键取出；铁砧锤长按右键并滑动可去掉标记（普通锤右键不改变状态）； 拆除时缓存与标记保留在掉落物中。左右键行为本身定义在 StoragePortBlockEntity，本类只负责掉落物、克隆与方块状态。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final BooleanProperty MARKED</code></td><td>是否有标记的方块状态<br>初值 <code>BooleanProperty.create(&quot;marked&quot;)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L36" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>@Override public boolean hasAnalogOutputSignal(BlockState state)</code></td><td>末尾返回 <code>true</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L38" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public StoragePortBlock(Properties properties)</code></td><td>实现调用 <code>super(properties)</code><br>实现调用 <code>this.registerDefaultState(this.defaultBlockState().setValue(StoragePortBlock.MARKED, false))</code><br>实现调用 <code>this.defaultBlockState().setValue(StoragePortBlock.MARKED, false)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L64" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public ItemStack getCloneItemStack( LevelReader level, BlockPos pos, BlockState state, boolean includeData, Player player )</code></td><td>末尾返回 <code>stack</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L88" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public BlockState playerWillDestroy(Level level, BlockPos pos, BlockState state, Player player)</code></td><td>末尾返回 <code>super.playerWillDestroy(level, pos, state, player)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L109" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public BlockEntity newBlockEntity(BlockPos blockPos, BlockState blockState)</code></td><td>为指定位置和状态创建方块实体。<br>末尾返回 <code>ModBlockEntities.STORAGE_PORT.create(blockPos, blockState)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L122" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public &lt;T extends BlockEntity&gt; BlockEntityTicker&lt;T&gt; getTicker( Level level, BlockState state, BlockEntityType&lt;T&gt; blockEntityType )</code></td><td><code>(level.isClientSide())</code> 成立时提前返回 <code>null</code><br>末尾返回 <code>createTickerHelper( blockEntityType, ModBlockEntities.STORAGE_PORT.get(), (level1, pos, state1, entity) -&gt; entity.tickServer() )</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortBlock.java#L128" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="storageportconsolidatorblock" tabindex="-1">StoragePortConsolidatorBlock <a class="header-anchor" href="#storageportconsolidatorblock" aria-label="Permalink to &quot;StoragePortConsolidatorBlock&quot;">​</a></h2><p><code>public class StoragePortConsolidatorBlock extends AbstractStoragePortBlock</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortConsolidatorBlock.java#L29" target="_blank" rel="noreferrer">类型声明</a></p><p>仓储端口整合器方块。 把相连仓储端口的内容物并成一个物品能力暴露给外部物流（漏斗、溜槽、AE 等模组的仓储总线）， 相连关系只沿端口延伸、不跨集装箱 / 存储站，且没有连接核心也能工作； 物品优先进入标记了对应物品的端口，双击右键把身上对应标记的物品全部存入。 左右键行为本身定义在 StoragePortConsolidatorBlockEntity。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public StoragePortConsolidatorBlock(Properties properties)</code></td><td>执行 <code>super(properties)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortConsolidatorBlock.java#L30" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>@Override public BlockState playerWillDestroy(Level level, BlockPos pos, BlockState state, Player player)</code></td><td>末尾返回 <code>super.playerWillDestroy(level, pos, state, player)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortConsolidatorBlock.java#L49" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public BlockEntity newBlockEntity(BlockPos blockPos, BlockState blockState)</code></td><td>为指定位置和状态创建方块实体。<br>末尾返回 <code>ModBlockEntities.STORAGE_PORT_CONSOLIDATOR.create(blockPos, blockState)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortConsolidatorBlock.java#L60" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public &lt;T extends BlockEntity&gt; BlockEntityTicker&lt;T&gt; getTicker( Level level, BlockState state, BlockEntityType&lt;T&gt; blockEntityType )</code></td><td><code>(level.isClientSide())</code> 成立时提前返回 <code>null</code><br>末尾返回 <code>createTickerHelper( blockEntityType, ModBlockEntities.STORAGE_PORT_CONSOLIDATOR.get(), (level1, pos, state1, entity) -&gt; entity.tickServer() )</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/logistics/storage/StoragePortConsolidatorBlock.java#L66" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table>',21)])])}const g=e(c,[["render",l]]);export{k as __pageData,g as default};
